    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string word;
    std::getline(std::cin, word);

    bool found = false;
    for (char c : word) {
        if (c == 'H' || c == 'Q' || c == '9') {
            found = true;
            break;
        }
    }

    std::cout << (found ? "YES" : "NO") << '\n';
    return 0;
}

